WITH CustomerSummary AS (SELECT customer_id, SUM(discount) AS total_discount, SUM(CASE WHEN channel = 'web' THEN 1 ELSE 0 END) AS web_count FROM orders WHERE order_date <= '2025-02-01' GROUP BY customer_id) SELECT c.id, c.name, c.is_active, C.total_discount, C.web_count FROM customers c INNER JOIN CustomerSummary C ON c.id = C.customer_id WHERE C.total_discount >= 2.3 ORDER BY web_count DESC, id LIMIT 10
